-- Photos and logos from Coasterpedia and English Wikipedia (images-pull.py, 2026-11-25).
CREATE TABLE IF NOT EXISTS open_images (source TEXT NOT NULL, ref TEXT NOT NULL, kind TEXT NOT NULL, file TEXT NOT NULL DEFAULT '', url TEXT, thumb TEXT, width INTEGER, height INTEGER, author TEXT, license TEXT, license_url TEXT, nonfree INTEGER NOT NULL DEFAULT 0, page TEXT, retrieved TEXT, taken TEXT, PRIMARY KEY (source, ref, kind, file));
